div.script:
function wangoSetStar(val) {
    var input = document.getElementById('wango_rating_input_val');
    if (input) input.value = val;
    var stars = document.querySelectorAll('#wango_star_picker .star-item');
    var labels = {
        1: '1 estrella (Pésimo)',
        2: '2 estrellas (Malo)',
        3: '3 estrellas (Regular)',
        4: '4 estrellas (Bueno)',
        5: '5 estrellas (Excelente)'
    };
    stars.forEach(function(s, idx) {
        if (idx < val) {
            s.className = 'fa fa-star star-item text-warning';
        } else {
            s.className = 'fa fa-star-o star-item text-muted';
        }
    });
    var lbl = document.getElementById('wango_star_label');
    if (lbl) lbl.textContent = labels[val] || '';
}
